import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/cases/[caseId]/page.schema.ts";

test("case-view is refused to someone signed in without cases.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("case-view sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("case-view opens to someone who holds cases.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["cases.read"] }), "allowed");
});
